// ASLChartButton.js - ASL Chart Reference Button with Embedded Images
// Place in: C:\Users\holly\QuietBakery\Scripts\ASLChartButton.js
// Images are embedded as base64 - NO external files needed!

(function() {
    'use strict';

    // Base64 encoded icon image (embedded directly)
    const ASL_ICON_BASE64 = 'data:image/png;base64,';

    // Base64 encoded chart image (embedded directly)
    const ASL_CHART_BASE64 = 'data:image/jpeg;base64,';

    // Use VNM's SceneManager to hook into game initialization
    const oldSceneManagerInitialize = SceneManager.initialize;
    SceneManager.initialize = function() {
        oldSceneManagerInitialize.call(this);
        // Wait for scene to be set up
        setTimeout(createASLChartButton, 1000);
    };

    function createASLChartButton() {
        // Remove any existing button first
        const existing = document.getElementById('aslChartButton');
        if (existing) {
            existing.remove();
        }

        // Create button container
        const button = document.createElement('div');
        button.id = 'aslChartButton';
        button.style.cssText = `
            position: fixed;
            top: 10px;
            right: 130px;
            width: 30px;
            height: 30px;
            background-color: white;
            border: 2px solid #8B6F47;
            border-radius: 50%;
            cursor: pointer;
            z-index: 9999;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 4px 15px rgba(0,0,0,0.3);
            transition: all 0.3s ease;
            padding: 4px;
        `;

        // Create icon image using embedded base64 data
        const icon = document.createElement('img');
        icon.src = ASL_ICON_BASE64;
        icon.alt = 'ASL';
        icon.style.cssText = `
            width: 100%;
            height: 100%;
            object-fit: contain;
        `;

        button.appendChild(icon);

        // Hover effect
        button.addEventListener('mouseenter', function() {
            button.style.borderColor = '#6B5638';
            button.style.transform = 'scale(1.1)';
        });
        button.addEventListener('mouseleave', function() {
            button.style.borderColor = '#8B6F47';
            button.style.transform = 'scale(1)';
        });

        // Click to open chart
        button.addEventListener('click', function() {
            openASLChart();
        });

        document.body.appendChild(button);
        console.log('ASL Chart button created with embedded images');
    }

    function openASLChart() {
        // Create overlay backdrop
        const overlay = document.createElement('div');
        overlay.id = 'aslChartOverlay';
        overlay.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.7);
            z-index: 10000;
            display: flex;
            align-items: center;
            justify-content: center;
            animation: fadeIn 0.2s;
        `;

        // Create popup container - narrower width to fit chart better
        const popup = document.createElement('div');
        popup.style.cssText = `
            background-color: white;
            padding: 15px;
            border-radius: 10px;
            width: 50vw;
            height: 80vh;
            max-width: 50vw;
            max-height: 80vh;
            position: relative;
            box-shadow: 0 4px 20px rgba(0,0,0,0.5);
            display: flex;
            flex-direction: column;
        `;

        // Create close button
        const closeBtn = document.createElement('button');
        closeBtn.textContent = '✕';
        closeBtn.style.cssText = `
            position: absolute;
            top: 8px;
            right: 8px;
            background: none;
            border: none;
            font-size: 20px;
            cursor: pointer;
            color: #666;
            width: 30px;
            height: 30px;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: color 0.2s;
        `;
        closeBtn.addEventListener('mouseenter', function() {
            closeBtn.style.color = '#333';
        });
        closeBtn.addEventListener('mouseleave', function() {
            closeBtn.style.color = '#666';
        });
        closeBtn.addEventListener('click', function() {
            document.body.removeChild(overlay);
        });

        // Create chart image using embedded base64 data
        const chartImg = document.createElement('img');
        chartImg.src = ASL_CHART_BASE64;
        chartImg.alt = 'ASL Alphabet Chart';
        chartImg.style.cssText = `
            width: 100%;
            height: 100%;
            object-fit: contain;
            display: block;
        `;

        popup.appendChild(closeBtn);
        popup.appendChild(chartImg);
        overlay.appendChild(popup);

        // Close on overlay click
        overlay.addEventListener('click', function(e) {
            if (e.target === overlay) {
                document.body.removeChild(overlay);
            }
        });

        // Add fade-in animation
        const style = document.createElement('style');
        style.textContent = `
            @keyframes fadeIn {
                from { opacity: 0; }
                to { opacity: 1; }
            }
        `;
        if (!document.getElementById('aslChartStyles')) {
            style.id = 'aslChartStyles';
            document.head.appendChild(style);
        }

        document.body.appendChild(overlay);
    }

})();

